Given a string s, we need to find the total number of non-empty distinct substrings that can be formed from the string.A substring is a contiguous sequence of characters within the string.Examples: Input : s = "abcd" Output : 10Explanation: All Distinct Substrings are ["abc", "ab", "a", "bcd", "bc", "b", "cd", "c", "d", "abcd"] Input : s = "aaa"Output : 3Explanation: All Distinct Substrings are ["aaa", "aa", "a"]Try It YourselfTable of Content[Naive Approach] - Generate All Substrings[Expected Approach] Using Trie Data Structure[Naive Approach] - Generate All SubstringsThe idea is simple, we generate all substrings of the given string and store them in a set, which automatically handles duplicates and ensures only unique substrings are kept. The size of the set at the end gives the number of distinct substrings.
            C++

    //Driver Code Starts
#include <iostream>
#include<vector>
using namespace std;
//Driver Code Ends


int countSubs(string &s)
{

    // To store distinct substrings
    unordered_set<string> st;

    // Generate substrings
    for (int i = 0; i < s.length(); i++) {
        string temp = "";
        for (int j = i; j < s.length(); j++) {
            temp.push_back(s[j]);
            st.insert(temp);
        }
    }
    //return distinct substrings
    return st.size();
}


//Driver Code Starts
int main()
{
    string s = "abcd";
    cout<<countSubs(s);
    return 0;
}

